query GetDiagnosticContexts {
  diagnosticContextDefinitions {
    id
    scoreIds
    params {
      key
      type
      required
      defaultValue
      validationRules {
        maxItems
        min
        max
        allowedValues
      }
    }
    timeFrameConfig {
      defaultDuration
      maxDurationDays
      maxDurationDays15m
      maxRetentionDays
      maxRetentionDays15m
    }
    layout
  }
  diagnosticContextLayouts {
    name
    widgets {
      name
      labels {
        key
        value
      }
      parameters {
        key
        value
      }
    }
  }
}
